import { Project } from '../../../../src'
import { path } from '@servicenow/sdk-build-core'
import { getMergedRecordUpdates, unzipInputArray, findInput } from '../test-utils'

describe('forEach Data Pill Type Annotation Replacement Tests', () => {
    /**
     * Test 1: Fluent to XML - Type Annotation Replacement
     *
     * Verifies that datapills with type annotations inside forEach loops are correctly
     * replaced with UUID-based references during Fluent → XML transformation.
     *
     * Tests both:
     * - Direct parameter reference: `wfa.dataPill(user, 'reference')` → `{{UUID.item|reference}}`
     * - Property access: `wfa.dataPill(user.email, 'string')` → `{{UUID.item.email|string}}`
     */
    test('Fluent to XML: forEach datapills with type annotations get UUID prefix', async () => {
        const project = new Project({ rootDir: path.resolve(__dirname, 'project') })

        const merged = await getMergedRecordUpdates(
            project,
            'foreach-datapill-type-annotations.now.ts',
            'flow-logics/fluent'
        )

        // Find the forEach flow logic instance
        const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
        expect(flowLogicInstances).toBeDefined()

        const forEachLoop = flowLogicInstances.find((instance) => instance.ui_id && !instance.parent_ui_id)
        expect(forEachLoop).toBeDefined()

        const forEachUUID = forEachLoop.ui_id
        expect(forEachUUID).toBeDefined()

        const actionInstances = merged['sys_hub_action_instance_v2']

        // Test 1a: Direct parameter reference with 'reference' type
        // wfa.dataPill(user, 'reference') should generate {{UUID.item|reference}}
        // Find the updateRecord action by checking for 'record' input after unzipping
        let updateAction: any
        for (const action of actionInstances) {
            if (action.parent_ui_id === forEachUUID && action.values) {
                const inputs = unzipInputArray(action.values)
                if (findInput(inputs, 'record')) {
                    updateAction = action
                    break
                }
            }
        }
        expect(updateAction).toBeDefined()

        const updateInputs = unzipInputArray(updateAction.values)
        const recordInput = findInput(updateInputs, 'record')

        expect(recordInput).toBeDefined()
        // Type annotations may be stripped in final XML, but UUID prefix should be applied
        expect(recordInput.value).toContain(`{{${forEachUUID}.item`)
        expect(recordInput.value).toMatch(new RegExp(`{{${forEachUUID}.item(|reference)?}}`))

        // Critical: Should NOT contain forEach prefix
        expect(recordInput.value).not.toContain('{{forEach.user')
        expect(recordInput.value).not.toContain('{{forEach.item')

        // Test 1b: Property access with 'string' type
        // wfa.dataPill(user.email, 'string') should generate {{UUID.item.email|string}}
        // Find the sendEmail action by checking for 'ah_to' input after unzipping
        let emailAction: any
        for (const action of actionInstances) {
            if (action.parent_ui_id === forEachUUID && action.values) {
                const inputs = unzipInputArray(action.values)
                if (findInput(inputs, 'ah_to')) {
                    emailAction = action
                    break
                }
            }
        }
        expect(emailAction).toBeDefined()

        const emailInputs = unzipInputArray(emailAction.values)
        const toInput = findInput(emailInputs, 'ah_to')

        expect(toInput).toBeDefined()
        // Type annotations may be stripped in final XML, but UUID prefix should be applied
        expect(toInput.value).toContain(`{{${forEachUUID}.item.email`)
        expect(toInput.value).toMatch(new RegExp(`{{${forEachUUID}.item.email(|string)?}}`))

        // Critical: Should NOT contain forEach prefix
        expect(toInput.value).not.toContain('{{forEach.user')
        expect(toInput.value).not.toContain('{{forEach.item')
    })

    /**
     * Test 2: Complete Round-Trip Verification
     *
     * Verifies that the complete transformation cycle (Fluent → XML) produces correct
     * UUID-based datapill references and does NOT contain any forEach.* references.
     *
     * This is the critical regression test ensuring the bug fix works correctly.
     */
    test('Round-trip: forEach datapills are UUID-prefixed, not forEach-prefixed', async () => {
        const project = new Project({ rootDir: path.resolve(__dirname, 'project') })

        const merged = await getMergedRecordUpdates(
            project,
            'foreach-datapill-type-annotations.now.ts',
            'flow-logics/fluent'
        )

        // Verify flow structure
        const flowRecords = merged['sys_hub_flow']
        expect(flowRecords).toBeDefined()
        expect(flowRecords.length).toBeGreaterThan(0)

        const flowRecord = flowRecords[0]
        expect(flowRecord.name).toBe('Weekly Deactivate Inactive Users')

        // Get forEach instance
        const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
        const forEachLoop = flowLogicInstances.find((instance: any) => instance.ui_id && !instance.parent_ui_id)
        expect(forEachLoop).toBeDefined()
        const forEachUUID = forEachLoop.ui_id

        // Verify all actions inside forEach
        const actionInstances = merged['sys_hub_action_instance_v2']
        const forEachActions = actionInstances.filter((a: any) => a.parent_ui_id === forEachUUID)

        // Should have at least 2 actions (updateRecord + sendEmail)
        expect(forEachActions.length).toBeGreaterThanOrEqual(2)

        // Critical verification: NO action should have forEach.user or forEach.item in values
        for (const action of forEachActions) {
            const inputs = unzipInputArray(action.values)
            const jsonString = JSON.stringify(inputs)

            // Should contain the forEach UUID (proof of UUID prefix)
            expect(jsonString).toContain(forEachUUID)

            // Critical: Should NOT contain forEach prefix with type annotation
            expect(jsonString).not.toContain('{{forEach.user|')
            expect(jsonString).not.toContain('{{forEach.user.')

            // Should NOT contain forEach.item pattern
            expect(jsonString).not.toMatch(/\{\{forEach\.user[.|]/)
            expect(jsonString).not.toMatch(/\{\{forEach\.item[.|]/)
        }
    })
})
